const app = document.querySelector('#app');
const cartKey='trs_cart_v1', wishKey='trs_wishlist_v1';
const state={ user:null,csrf:'',store:null,admin:null,cart:readLocal(cartKey,[]),wishlist:readLocal(wishKey,[]),selectedVariants:{},selectedImages:{},pendingProductImages:[],accountTab:'orders',couponCode:'',couponMessage:'',listing:{query:'',category:'',sort:'newest',filters:{}},notice:'' };

function readLocal(key,fallback){try{return JSON.parse(localStorage.getItem(key))||fallback}catch{return fallback}}
function saveLocal(key,value){localStorage.setItem(key,JSON.stringify(value))}
function esc(value){return String(value??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]))}
function money(value){return new Intl.NumberFormat('en-IN',{style:'currency',currency:state.store?.settings?.currency||'INR',maximumFractionDigits:0}).format(Number(value)||0)}
function date(value){return value?new Intl.DateTimeFormat('en-IN',{dateStyle:'medium'}).format(new Date(value)):'-'}
function time(value){return value?new Intl.DateTimeFormat('en-IN',{dateStyle:'medium',timeStyle:'short'}).format(new Date(value)):'-'}
function productById(id){return state.store?.products?.find(p=>p.id===id)}
function selectedVariant(p){return p?.variants?.find(v=>v.id===state.selectedVariants[p.id])||p?.variants?.find(v=>v.stock>0)||p?.variants?.[0]||null}
function productCategory(p){return state.store?.categories?.find(c=>c.id===p.categoryId)}
function routeTo(path){history.pushState({},'',path);window.scrollTo(0,0);render()}
function toast(message,error=false){const stack=document.querySelector('.toast-stack')||Object.assign(document.body.appendChild(document.createElement('div')),{className:'toast-stack'});const el=document.createElement('div');el.className=`toast${error?' error':''}`;el.textContent=message;stack.append(el);setTimeout(()=>el.remove(),3000)}
async function request(path,options={}){
  const headers={'content-type':'application/json',...(options.headers||{})};
  if(options.method && options.method!=='GET' && state.csrf)headers['x-csrf-token']=state.csrf;
  const response=await fetch(path,{credentials:'same-origin',...options,headers,body:options.body===undefined?undefined:JSON.stringify(options.body)});
  const result=await response.json().catch(()=>({}));
  if(!response.ok){const error=new Error(result.error||'Something went wrong.');error.status=response.status;throw error}
  return result;
}
async function refreshStore(){state.store=await request('/api/store')}
async function refreshAdmin(){state.admin=await request('/api/admin')}
function image(url,alt=''){return `<img src="${esc(url||'/logo.png')}" alt="${esc(alt)}" loading="lazy" onerror="this.onerror=null;this.src='/logo.png'">`}
function navActive(path){return location.pathname===path?'active':''}
function siteHeader(){
  const categories=state.store?.categories||[];const count=state.cart.reduce((n,x)=>n+x.quantity,0);const wishCount=state.wishlist.length;
  return `<div class="announcement">Reliable technology. Clear advice. Support when you need it.</div><header class="site-header"><div class="header-main"><a href="/" data-route="/" class="brand">${image('/logo.png','Tech Refresh Solution')}<span class="brand-copy">TECH REFRESH SOLUTION<small>All in One IT Solution</small></span></a><form class="search-wrap" id="search-form"><span class="search-icon" aria-hidden="true">⌕</span><label class="sr-only" for="site-search">Search products</label><input id="site-search" name="q" placeholder="Search laptops, networking, accessories..." value="${esc(new URLSearchParams(location.search).get('q')||'')}" list="product-suggestions" autocomplete="off"><datalist id="product-suggestions">${(state.store?.products||[]).map(p=>`<option value="${esc(p.name)}">`).join('')}</datalist></form><div class="header-actions"><button class="icon-action" data-route="/account" title="Account"><span aria-hidden="true">♙</span><span class="action-label">${state.user?esc(state.user.name.split(' ')[0]):'Sign in'}</span></button><button class="icon-action" data-route="/wishlist" title="Wishlist"><span aria-hidden="true">♡</span>${wishCount?`<span class="count">${wishCount}</span>`:''}</button><button class="icon-action" data-route="/cart" title="Cart"><span aria-hidden="true">▱</span>${count?`<span class="count">${count}</span>`:''}</button><a class="icon-action action-label" href="/admin" data-route="/admin" title="Admin portal">Admin</a></div></div><nav class="category-nav"><div class="category-nav-inner"><a href="/" data-route="/" class="all-link ${navActive('/')}">Shop all</a>${categories.map(c=>`<a href="/category/${esc(c.slug)}" data-route="/category/${esc(c.slug)}" class="${location.pathname===`/category/${c.slug}`?'active':''}">${esc(c.name)}</a>`).join('')}<a href="/orders" data-route="/orders">Track order</a></div></nav></header>`
}
function footer(){return `<footer class="site-footer"><div class="footer-main"><div class="footer-brand"><a href="/" data-route="/" class="brand">${image('/logo.png','Tech Refresh Solution')}<span class="brand-copy">TECH REFRESH SOLUTION<small>All in One IT Solution</small></span></a><p>Thoughtful technology and dependable support for work, home and everything in between.</p></div><div class="footer-col"><h3>Shop</h3><a href="/" data-route="/">All products</a>${(state.store?.categories||[]).slice(0,4).map(c=>`<a href="/category/${esc(c.slug)}" data-route="/category/${esc(c.slug)}">${esc(c.name)}</a>`).join('')}</div><div class="footer-col"><h3>Customer care</h3><a href="/account" data-route="/account">My account</a><a href="/orders" data-route="/orders">Order tracking</a><a href="mailto:hello@techrefreshsolution.com">Contact support</a></div><div class="footer-col"><h3>Information</h3><a href="#" data-static="About us">About us</a><a href="#" data-static="Shipping policy">Shipping policy</a><a href="#" data-static="Returns & warranty">Returns & warranty</a></div></div><div class="footer-bottom"><span>© ${new Date().getFullYear()} Tech Refresh Solution</span><span>Made for useful technology, chosen well.</span></div></footer>`}
function productCard(p){const cat=productCategory(p);const saved=state.wishlist.includes(p.id);const discount=p.mrp>p.price?Math.round((1-p.price/p.mrp)*100):0;return `<article class="product-card"><div class="product-visual"><a href="/product/${esc(p.slug)}" data-route="/product/${esc(p.slug)}">${image(p.image,p.name)}</a>${discount?`<span class="product-tag">Save ${discount}%</span>`:''}<button class="wish-button ${saved?'on':''}" data-action="wish" data-id="${p.id}" aria-label="${saved?'Remove from':'Add to'} wishlist" title="Wishlist">${saved?'♥':'♡'}</button></div><div class="product-info"><div class="product-category">${esc(cat?.name||'Products')}</div><a class="product-name" href="/product/${esc(p.slug)}" data-route="/product/${esc(p.slug)}">${esc(p.name)}</a><div class="product-price"><strong>${money(p.price)}</strong>${p.mrp>p.price?`<del>${money(p.mrp)}</del>`:''}</div><div class="product-stock">${p.stock>0?`${p.stock<6?'Only ':''}${p.stock} in stock`:'Made to order'}</div><div class="product-actions"><button class="btn primary" data-action="add-cart" data-id="${p.id}" ${!p.stock&&!p.madeToOrder?'disabled':''}>Add to cart</button><a class="btn secondary" href="/product/${esc(p.slug)}" data-route="/product/${esc(p.slug)}" title="View product">↗</a></div></div></article>`}
function productGrid(products){return products.length?`<div class="product-grid">${products.map(productCard).join('')}</div>`:`<div class="empty-state"><h3>No products found</h3><p>Try a different search or clear a filter.</p><button class="btn secondary" data-action="clear-filters">Clear filters</button></div>`}
function homePage(){const products=state.store.products;const banner=state.store.banners[0]||{};const featured=products.filter(p=>p.tags?.includes('featured')).slice(0,4);const latest=products.slice().sort((a,b)=>new Date(b.createdAt)-new Date(a.createdAt)).slice(0,4);return `<main class="page"><section class="home-hero"><div class="hero-copy"><div class="eyebrow">Technology, chosen with care</div><h1>${esc(banner.title||'Technology that fits your day')}</h1><p>${esc(banner.subtitle||'Reliable essentials, helpful advice and the support to make your setup work better.')}</p><a class="btn primary" href="/" data-route="/">Explore the collection <span aria-hidden="true">→</span></a></div><div class="hero-photo">${image(banner.image,'A modern workspace with technology') }<div class="hero-overlay"></div><div class="hero-note"><strong>Good tools. Better days.</strong>Everyday technology, made easier.</div></div></section><div class="benefit-strip"><div class="benefit"><span class="benefit-mark">✓</span><div><strong>Genuine products</strong><span>Carefully sourced essentials</span></div></div><div class="benefit"><span class="benefit-mark">↗</span><div><strong>Helpful expertise</strong><span>Guidance before and after</span></div></div><div class="benefit"><span class="benefit-mark">⌂</span><div><strong>Free delivery over ${money(state.store.settings.freeShippingAt)}</strong><span>Clear shipping at checkout</span></div></div><div class="benefit"><span class="benefit-mark">◎</span><div><strong>Secure checkout</strong><span>Pay on delivery available</span></div></div></div><section class="section"><div class="section-head"><div><h2>Shop by category</h2><p>Find the right technology for the way you work.</p></div></div><div class="category-grid">${state.store.categories.map((c,i)=>`<a class="category-tile" href="/category/${esc(c.slug)}" data-route="/category/${esc(c.slug)}"><div><strong>${esc(c.name)}</strong><span>${esc(c.description||`${products.filter(p=>p.categoryId===c.id).length} useful picks`)}</span></div><span class="category-arrow" aria-hidden="true">→</span></a>`).join('')}</div></section><section class="section"><div class="section-head"><div><h2>Selected for you</h2><p>Customer favourites and new essentials.</p></div><a href="/" data-route="/" class="link-button">Shop all products →</a></div>${productGrid(featured.length?featured:products.slice(0,4))}</section><div class="wide-promo"><div><h2>Build a setup that works for you.</h2><p>From the first device to the last cable, get practical advice from our team.</p></div><a class="btn primary" href="mailto:hello@techrefreshsolution.com">Talk to our team <span aria-hidden="true">→</span></a></div><section class="section"><div class="section-head"><div><h2>Just arrived</h2><p>Fresh picks for your desk, home and team.</p></div></div>${productGrid(latest)}</section><div class="trust-note"><div class="trust-item"><span>✓</span><span><b>Thoughtful selection</b> from trusted brands</span></div><div class="trust-item"><span>◇</span><span><b>Practical support</b> when you need it</span></div><div class="trust-item"><span>↺</span><span><b>Warranty support</b> on eligible products</span></div></div></main>`}
function catalogPage(){const params=new URLSearchParams(location.search);const cat=state.store.categories.find(c=>c.slug===location.pathname.split('/').pop());const query=(params.get('q')||'').trim();let products=state.store.products.filter(p=>!cat||p.categoryId===cat.id);if(query)products=products.filter(p=>`${p.name} ${p.description} ${productCategory(p)?.name||''} ${Object.values(p.attributes||{}).join(' ')}`.toLowerCase().includes(query.toLowerCase()));if(state.listing.filters.inStock)products=products.filter(p=>p.stock>0||p.madeToOrder);if(state.listing.filters.maxPrice)products=products.filter(p=>p.price<=Number(state.listing.filters.maxPrice));for(const [key,val] of Object.entries(state.listing.filters.attrs||{})){if(val)products=products.filter(p=>String(p.attributes?.[key]||'').toLowerCase().includes(val.toLowerCase()))}const sort=params.get('sort')||state.listing.sort;if(sort==='price-low')products.sort((a,b)=>a.price-b.price);if(sort==='price-high')products.sort((a,b)=>b.price-a.price);if(sort==='newest')products.sort((a,b)=>new Date(b.createdAt)-new Date(a.createdAt));if(sort==='popular')products.sort((a,b)=>(b.tags?.includes('featured')?1:0)-(a.tags?.includes('featured')?1:0));const attrs=[...new Set(products.flatMap(p=>Object.keys(p.attributes||{})))].slice(0,3);return `<main class="page"><div class="crumbs"><a href="/" data-route="/">Home</a> / ${esc(cat?.name|| (query?`Search: ${query}`:'All products'))}</div><div class="page-title"><div><h1>${esc(cat?.name|| (query?'Search results':'All products'))}</h1><p>${esc(cat?.description|| (query?`Results matching “${query}”`:'Thoughtful technology for home, work and beyond.'))}</p></div></div><div class="shop-layout"><aside class="filters"><div class="filter-toolbar-mobile"><h2 class="filter-title">Filter products</h2><button class="link-button" data-action="clear-filters">Clear</button></div><div class="filter-group"><label class="label">Availability</label><label class="check-line"><input type="checkbox" data-filter="inStock" ${state.listing.filters.inStock?'checked':''}> In stock or made to order</label></div><div class="filter-group"><label class="label" for="max-price">Maximum price</label><div class="filter-price"><input id="max-price" data-filter-value="maxPrice" type="number" min="0" placeholder="No limit" value="${esc(state.listing.filters.maxPrice||'')}"></div></div>${attrs.map(attr=>`<div class="filter-group"><label class="label" for="filter-${esc(attr)}">${esc(attr)}</label><select id="filter-${esc(attr)}" data-filter-attr="${esc(attr)}" class="field"><option value="">Any</option>${[...new Set(products.map(p=>p.attributes?.[attr]).filter(Boolean))].map(v=>`<option ${state.listing.filters.attrs?.[attr]===v?'selected':''}>${esc(v)}</option>`).join('')}</select></div>`).join('')}</aside><section class="listing-results"><div class="listing-toolbar"><p>${products.length} ${products.length===1?'product':'products'}</p><label class="sr-only" for="sort-products">Sort products</label><select id="sort-products" data-action="sort"><option value="newest" ${sort==='newest'?'selected':''}>Newest first</option><option value="popular" ${sort==='popular'?'selected':''}>Featured</option><option value="price-low" ${sort==='price-low'?'selected':''}>Price: low to high</option><option value="price-high" ${sort==='price-high'?'selected':''}>Price: high to low</option></select></div>${productGrid(products)}</section></div></main>`}
function reviewBlock(p){const list=(state.store.reviews||[]).filter(r=>r.productId===p.id);const eligible=state.user?.kind==='customer'&&(state.userOrders||[]).some(o=>o.items.some(i=>i.productId===p.id));const already=state.store.reviews?.some(r=>r.productId===p.id&&r.customerId===state.user?.id);return `<section class="section"><div class="section-head"><div><h2>Customer reviews</h2><p>${list.length?`${list.length} verified ${list.length===1?'review':'reviews'}`:'No reviews yet'}</p></div></div>${list.map(r=>`<div class="surface" style="margin-bottom:8px"><div class="rating">${'★'.repeat(r.rating)}${'☆'.repeat(5-r.rating)} <span>${esc(r.customerName)} · verified purchase · ${date(r.createdAt)}</span></div><p>${esc(r.comment)}</p></div>`).join('')}${eligible&&!already?`<form id="review-form" class="surface"><h3 class="form-title">Share your experience</h3><input type="hidden" name="productId" value="${p.id}"><div class="form-grid"><label class="form-field"><span>Rating</span><select name="rating"><option value="5">5 - Excellent</option><option value="4">4 - Good</option><option value="3">3 - Fine</option><option value="2">2 - Not great</option><option value="1">1 - Poor</option></select></label><label class="form-field wide"><span>Review</span><textarea name="comment" required minlength="8" placeholder="What should another customer know?"></textarea></label></div><button class="btn primary" style="margin-top:10px">Submit review</button></form>`:state.user?.kind==='customer'&&already?`<p class="form-help">You have already reviewed this product or your review is awaiting approval.</p>`:`<p class="form-help">Reviews are available to customers who have purchased this product.</p>`}</section>`}
function productPageBasic(){const slug=decodeURIComponent(location.pathname.split('/').pop());const p=state.store.products.find(x=>x.slug===slug);if(!p)return `<main class="page"><div class="empty-state"><h3>Product not found</h3><p>This product may have been removed.</p><a class="btn secondary" href="/" data-route="/">Back to shop</a></div></main>`;const cat=productCategory(p);const related=state.store.products.filter(x=>x.categoryId===p.categoryId&&x.id!==p.id).slice(0,4);const variant=selectedVariant(p);const price=variant?.price??p.price;const stock=variant?.stock??p.stock;const variantPicker=p.variants?.length?`<label class="form-field variant-picker"><span>Choose an option</span><select id="variant-choice">${p.variants.map(v=>`<option value="${v.id}" ${v.id===variant.id?'selected':''} ${!v.stock?'disabled':''}>${esc(v.label)} · ${money(v.price)} · ${v.stock} available</option>`).join('')}</select></label>`:'';let view=`<main class="page"><div class="crumbs"><a href="/" data-route="/">Home</a> / <a href="/category/${esc(cat?.slug||'')}" data-route="/category/${esc(cat?.slug||'')}">${esc(cat?.name||'Products')}</a> / ${esc(p.name)}</div><section class="detail-grid"><div><div class="detail-image">${image(p.image,p.name)}</div><div class="detail-thumbs"><button aria-label="Product image">${image(p.image,p.name)}</button></div></div><div class="detail-copy"><div class="product-category">${esc(cat?.name||'Product')}</div><h1>${esc(p.name)}</h1><div class="rating">★★★★★ <span>Verified customer reviews</span></div><div class="detail-price"><strong>${money(p.price)}</strong>${p.mrp>p.price?`<del>${money(p.mrp)}</del><span class="discount">${Math.round((1-p.price/p.mrp)*100)}% off</span>`:''}</div><p class="detail-desc">${esc(p.description||'Reliable technology, chosen for everyday use.')}</p><div class="stock-line">${p.stock>0?`✓ In stock · ${p.stock} available`:p.madeToOrder?'Made to order':'Currently unavailable'}</div>${Object.entries(p.attributes||{}).map(([k,v])=>`<div class="attr-row"><span>${esc(k)}</span><b>${esc(v)}</b></div>`).join('')}<div class="qty-control"><button data-action="detail-qty" data-delta="-1" aria-label="Decrease quantity">−</button><span id="detail-qty">1</span><button data-action="detail-qty" data-delta="1" aria-label="Increase quantity">+</button></div><div class="detail-actions"><button class="btn primary" data-action="add-cart" data-id="${p.id}" data-detail="true" ${!p.stock&&!p.madeToOrder?'disabled':''}>Add to cart</button><button class="btn secondary" data-action="buy-now" data-id="${p.id}" ${!p.stock&&!p.madeToOrder?'disabled':''}>Buy now</button><button class="icon-action" data-action="wish" data-id="${p.id}" title="Add to wishlist">${state.wishlist.includes(p.id)?'♥':'♡'}</button></div><div class="delivery-box"><b>Need a hand choosing?</b><br>Our team can help you find a setup that suits your space and budget.</div></div></section><section class="section"><div class="section-head"><div><h2>Product details</h2><p>Specifications provided for this product.</p></div></div><table class="spec-table"><tbody><tr><th>SKU</th><td>${esc(p.sku)}</td></tr><tr><th>Category</th><td>${esc(cat?.name||'')}</td></tr>${Object.entries(p.attributes||{}).map(([k,v])=>`<tr><th>${esc(k)}</th><td>${esc(v)}</td></tr>`).join('')}</tbody></table></section>${reviewBlock(p)}${related.length?`<section class="section"><div class="section-head"><div><h2>More from ${esc(cat?.name||'this range')}</h2></div></div>${productGrid(related)}</section>`:''}</main>`;if(variant){view=view.replace(`<div class="detail-price"><strong>${money(p.price)}</strong>`,`<div class="detail-price"><strong>${money(price)}</strong>`).replace(`<div class="stock-line">${p.stock>0?`✓ In stock · ${p.stock} available`:p.madeToOrder?'Made to order':'Currently unavailable'}</div>`,`<div class="stock-line">${stock>0?`✓ In stock · ${stock} available`:'Currently unavailable'}</div>`).replace('<div class="detail-price">',`${variantPicker}<div class="detail-price">`).replace(`data-detail="true"`,`data-detail="true" data-variant-id="${variant.id}"`).replace(`data-action="buy-now" data-id="${p.id}"`,`data-action="buy-now" data-id="${p.id}" data-variant-id="${variant.id}"`).replace(`<td>${esc(p.sku)}</td>`,`<td>${esc(variant.sku)}</td>`)}return view}
function productPage(){const p=state.store?.products?.find(x=>x.slug===decodeURIComponent(location.pathname.split('/').pop()));const html=productPageBasic();if(!p)return html;const images=p.images?.length?p.images:[p.image];if(images.length<2)return html;const current=state.selectedImages[p.id]||images[0];const old=`<div class="detail-image">${image(p.image,p.name)}</div><div class="detail-thumbs"><button aria-label="Product image">${image(p.image,p.name)}</button></div>`;const gallery=`<div class="detail-image">${image(current,p.name)}</div><div class="detail-thumbs">${images.map((src,i)=>`<button data-action="select-product-image" data-id="${p.id}" data-src="${esc(src)}" aria-label="Show product image ${i+1}">${image(src,p.name)}</button>`).join('')}</div>`;return html.replace(old,gallery)}
function cartLines(){return state.cart.map(line=>({line,p:productById(line.productId)})).filter(x=>x.p)}
function quote(){const lines=cartLines();const lineTotal=x=>(x.p.variants?.find(v=>v.id===x.line.variantId)?.price??x.p.price)*x.line.quantity;const subtotal=lines.reduce((n,x)=>n+lineTotal(x),0);const coupon=state.store?.coupons?.find(c=>c.code.toLowerCase()===state.couponCode.toLowerCase());const eligible=lines.filter(x=>!coupon?.productIds?.length||coupon.productIds.includes(x.p.id)).reduce((n,x)=>n+lineTotal(x),0);const discount=!coupon?0:coupon.type==='percent'?Math.round(eligible*coupon.value/100):Math.min(eligible,Number(coupon.value));const shipping=subtotal-discount>=Number(state.store.settings.freeShippingAt)?0:Number(state.store.settings.shippingFlat);const tax=Math.round(Math.max(0,subtotal-discount)*Number(state.store.settings.taxRate)/100);return {subtotal,discount,shipping,tax,total:subtotal-discount+shipping+tax}}
function summaryBox(){const q=quote();return `<aside class="summary-box"><h2>Order summary</h2><div class="sum-line"><span>Subtotal</span><b>${money(q.subtotal)}</b></div>${q.discount?`<div class="sum-line"><span>Coupon savings</span><b>−${money(q.discount)}</b></div>`:''}<div class="sum-line"><span>Shipping</span><b>${q.shipping?money(q.shipping):'Free'}</b></div><div class="sum-line"><span>Estimated tax</span><b>${money(q.tax)}</b></div><div class="sum-line sum-total"><span>Total</span><b>${money(q.total)}</b></div><p class="secure-note">Final tax and shipping are confirmed by the server at order placement.</p></aside>`}
function cartPage(){const rows=cartLines();if(!rows.length)return `<main class="page"><div class="page-title"><div><h1>Your cart</h1><p>Your selected products will appear here.</p></div></div><div class="empty-state"><h3>Your cart is empty</h3><p>Find something useful for your setup.</p><a class="btn primary" href="/" data-route="/">Continue shopping</a></div></main>`;return `<main class="page"><div class="crumbs"><a href="/" data-route="/">Shop</a> / Cart</div><div class="page-title"><div><h1>Your cart</h1><p>${rows.length} ${rows.length===1?'item':'items'} ready for checkout</p></div><button class="link-button" data-action="clear-cart">Remove all</button></div><div class="cart-layout"><section class="surface">${rows.map(({line,p})=>{const v=p.variants?.find(x=>x.id===line.variantId);const price=v?.price??p.price;return `<div class="cart-row"><a href="/product/${esc(p.slug)}" data-route="/product/${esc(p.slug)}">${image(p.image,p.name)}</a><div><h3><a href="/product/${esc(p.slug)}" data-route="/product/${esc(p.slug)}">${esc(p.name)}</a></h3><p>SKU ${esc(v?.sku||p.sku)}${v?` · ${esc(v.label)}`:''}</p><div class="cart-row-actions"><button data-action="qty" data-id="${p.id}" data-variant-id="${v?.id||''}" data-delta="-1" aria-label="Decrease quantity">−</button><span>${line.quantity}</span><button data-action="qty" data-id="${p.id}" data-variant-id="${v?.id||''}" data-delta="1" aria-label="Increase quantity">+</button><button class="link-button" data-action="remove-cart" data-id="${p.id}" data-variant-id="${v?.id||''}">Remove</button></div></div><div class="cart-row-price"><strong>${money(price*line.quantity)}</strong><p>${money(price)} each</p></div></div>`}).join('')}</section><div>${summaryBox()}<div class="coupon-form"><label class="sr-only" for="coupon-code">Coupon code</label><input id="coupon-code" class="input" placeholder="Promo code" value="${esc(state.couponCode)}"><button class="btn secondary" data-action="apply-coupon">Apply</button></div>${state.couponMessage?`<p class="${state.couponCode?'form-success':'form-error'}">${esc(state.couponMessage)}</p>`:''}<button class="btn primary full" data-action="checkout">Continue to checkout →</button><a class="btn secondary full" style="margin-top:8px" href="/" data-route="/">Continue shopping</a></div></div></main>`}
function checkoutPage(){if(!cartLines().length)return cartPage();if(!state.user||state.user.kind!=='customer')return authPage('login','/checkout');const saved=state.user.addresses?.[0]||{};const online=state.store.settings.onlinePaymentEnabled;return `<main class="page"><div class="crumbs"><a href="/cart" data-route="/cart">Cart</a> / Checkout</div><div class="page-title"><div><h1>Checkout</h1><p>Confirm your delivery details and payment method.</p></div></div><div class="checkout-progress"><span class="active">1. Delivery</span><i></i><span class="active">2. Payment</span><i></i><span>3. Confirmation</span></div><form id="checkout-form" class="checkout-layout"><section class="surface"><div class="form-section"><h2 class="form-title">Delivery address</h2>${state.user.addresses?.length>1?`<label class="form-field"><span>Saved addresses</span><select id="checkout-address">${state.user.addresses.map((a,i)=>`<option value="${i}">${esc(a.name)} · ${esc(a.city)} ${esc(a.postalCode)}</option>`).join('')}<option value="new">Enter a new address</option></select></label>`:''}<div class="form-grid"><label class="form-field"><span>Full name</span><input name="name" required value="${esc(saved.name||state.user.name)}"></label><label class="form-field"><span>Phone</span><input name="phone" required inputmode="tel" value="${esc(saved.phone||state.user.phone||'')}"></label><label class="form-field wide"><span>Address</span><input name="line1" required placeholder="House, street and area" value="${esc(saved.line1||'')}"></label><label class="form-field wide"><span>Apartment, suite or landmark (optional)</span><input name="line2" value="${esc(saved.line2||'')}"></label><label class="form-field"><span>City</span><input name="city" required value="${esc(saved.city||'')}"></label><label class="form-field"><span>State</span><input name="state" required value="${esc(saved.state||'')}"></label><label class="form-field"><span>PIN code</span><input name="postalCode" required inputmode="numeric" pattern="[0-9]{6}" value="${esc(saved.postalCode||'')}"></label><label class="form-field"><span>Email</span><input value="${esc(state.user.email)}" disabled></label></div></div><div class="form-section"><h2 class="form-title">Payment method</h2>${state.store.settings.codEnabled?`<label class="payment-option selected"><input type="radio" name="paymentMethod" value="cod" checked> <span><b>Cash on delivery</b><br><span class="form-help">Pay when your order arrives.</span></span></label>`:''}<label class="payment-option ${online?'':'disabled'}"><input type="radio" name="paymentMethod" value="gateway" ${online?'':'disabled'} ${state.store.settings.codEnabled?'':'checked'}> <span><b>Online payment</b><br><span class="form-help">Card, UPI, net banking and wallets · ${online?'secure Razorpay checkout':'configure Razorpay keys to enable'}</span></span></label></div><div id="checkout-error"></div><button class="btn primary" type="submit">Place order · ${money(quote().total)}</button><p class="secure-note">Your payment details are handled by the selected payment provider.</p></section><div>${summaryBox()}</div></form></main>`}
function authPage(mode='login',next='/account'){const isRegister=mode==='register';return `<main class="page"><section class="auth-layout"><div class="auth-intro"><img src="/logo.png" alt="Tech Refresh Solution"><div><h2>Technology that works for you.</h2><p>Sign in to manage orders, addresses and helpful support in one place.</p></div></div><div class="auth-main"><h1>${isRegister?'Create your account':'Welcome back'}</h1><p>${isRegister?'A few details and you’re ready to shop.':'Sign in to continue to your account.'}</p><form id="${isRegister?'register-form':'login-form'}" data-next="${esc(next)}">${isRegister?`<label class="form-field"><span>Full name</span><input name="name" required autocomplete="name"></label>`:''}<label class="form-field"><span>Email address</span><input name="email" required type="email" autocomplete="email"></label>${isRegister?`<label class="form-field"><span>Phone (optional)</span><input name="phone" inputmode="tel" autocomplete="tel"></label>`:''}<label class="form-field"><span>Password</span><input name="password" required type="password" minlength="${isRegister?8:1}" autocomplete="${isRegister?'new-password':'current-password'}"></label><div id="auth-error"></div><button class="btn primary full" style="margin-top:9px">${isRegister?'Create account':'Sign in'}</button></form><div class="auth-switch">${isRegister?'Already have an account?':'New to Tech Refresh Solution?'} <button class="link-button" data-route="/${isRegister?'login':'register'}" data-next="${esc(next)}">${isRegister?'Sign in':'Create an account'}</button></div>${next.startsWith('/admin')?`<p class="form-help">Store administrators can sign in with their staff account.</p>`:''}</div></section></main>`}
function orderCard(o){return `<article class="order-card"><div class="order-top"><div><b>${esc(o.id)}</b><br><span>Placed ${date(o.createdAt)}</span></div><span class="status-label">${esc(o.status)}</span></div><div class="order-bottom"><span>${o.items.length} ${o.items.length===1?'item':'items'} · ${esc(o.paymentMethod==='cod'?'Cash on delivery':'Online payment')}</span><b>${money(o.total)}</b></div><div class="order-bottom"><span>${o.items.map(i=>esc(i.name)).join(', ')}</span><a class="link-button" href="/invoice/${esc(o.id)}" data-route="/invoice/${esc(o.id)}">Invoice</a></div></article>`}
function accountPage(){if(!state.user)return authPage('login','/account');if(state.user.kind==='admin')return `<main class="page"><div class="empty-state"><h3>You’re signed in as an administrator</h3><p>Open the back office to manage the store.</p><a href="/admin" data-route="/admin" class="btn primary">Open admin dashboard</a></div></main>`;const orders=state.userOrders||[];const tab=state.accountTab||'orders';let pane='';if(tab==='orders')pane=`<div class="section-head"><div><h2>Recent orders</h2><p>Track delivery and revisit past purchases.</p></div></div>${orders.length?orders.map(orderCard).join(''):`<div class="empty-state"><h3>No orders yet</h3><p>Your order history will show here.</p><a href="/" data-route="/" class="btn secondary">Explore products</a></div>`}`;if(tab==='profile')pane=`<form id="profile-form" class="surface"><h2 class="form-title">Profile details</h2><div class="form-grid"><label class="form-field"><span>Name</span><input name="name" required value="${esc(state.user.name)}"></label><label class="form-field"><span>Phone</span><input name="phone" value="${esc(state.user.phone||'')}"></label><label class="form-field wide"><span>Email</span><input value="${esc(state.user.email)}" disabled></label></div><div id="profile-result"></div><button class="btn primary" style="margin-top:12px">Save profile</button></form>`;if(tab==='addresses')pane=`<section class="surface"><h2 class="form-title">Saved delivery addresses</h2>${(state.user.addresses||[]).map((a,i)=>`<div class="order-card"><div class="order-top"><b>${esc(a.name)} · ${esc(a.phone)}</b><button class="link-button" data-action="delete-address" data-index="${i}">Remove</button></div><div class="order-bottom"><span>${esc(a.line1)} ${esc(a.line2||'')}<br>${esc(a.city)}, ${esc(a.state)} ${esc(a.postalCode)}</span></div></div>`).join('')||`<p class="form-help">No saved addresses yet.</p>`}<form id="address-form" class="form-grid" style="margin-top:14px"><label class="form-field"><span>Full name</span><input name="name" required value="${esc(state.user.name)}"></label><label class="form-field"><span>Phone</span><input name="phone" required value="${esc(state.user.phone||'')}"></label><label class="form-field wide"><span>Address</span><input name="line1" required></label><label class="form-field wide"><span>Apartment, suite or landmark</span><input name="line2"></label><label class="form-field"><span>City</span><input name="city" required></label><label class="form-field"><span>State</span><input name="state" required></label><label class="form-field"><span>PIN code</span><input name="postalCode" required pattern="[0-9]{6}"></label><span></span><div id="address-result" class="form-field wide"></div><button class="btn primary">Add address</button></form></section>`;return `<main class="page"><div class="page-title"><div><h1>Your account</h1><p>Welcome, ${esc(state.user.name)}.</p></div><button class="btn secondary" data-action="logout">Sign out</button></div><div class="account-layout"><aside class="account-nav"><h3>Account</h3><button class="${tab==='orders'?'active':''}" data-account-tab="orders">Orders</button><button class="${tab==='addresses'?'active':''}" data-account-tab="addresses">Addresses</button><button class="${tab==='profile'?'active':''}" data-account-tab="profile">Profile</button></aside><section class="account-content" id="account-content">${pane}</section></div></main>`}
function invoicePage(){const id=decodeURIComponent(location.pathname.split('/').pop());const o=(state.userOrders||[]).find(x=>x.id===id)||(state.admin?.orders||[]).find(x=>x.id===id);if(!o)return `<main class="page"><div class="empty-state"><h3>Invoice not available</h3><p>Sign in to the account used for this order.</p><a href="/login" data-route="/login" class="btn secondary">Sign in</a></div></main>`;return `<main class="page"><div class="surface" style="max-width:850px;margin:auto"><div class="page-title"><div><div class="brand">${image('/logo.png','Tech Refresh Solution')}<span class="brand-copy">TECH REFRESH SOLUTION<small>All in One IT Solution</small></span></div><h1 style="margin-top:20px">Order invoice</h1><p>${esc(o.id)} · ${date(o.createdAt)}</p></div><button class="btn secondary" onclick="window.print()">Print invoice</button></div><div class="form-grid"><div><b>Bill to</b><div>${esc(o.customerName)}</div><div>${esc(o.email)}</div></div><div><b>Ship to</b><div>${esc(o.address.name)}</div><div>${esc(o.address.line1)} ${esc(o.address.line2||'')}</div><div>${esc(o.address.city)}, ${esc(o.address.state)} ${esc(o.address.postalCode)}</div></div></div><div class="table-wrap" style="margin-top:20px"><table class="data-table"><thead><tr><th>Product</th><th>SKU</th><th>Qty</th><th>Unit price</th><th>Total</th></tr></thead><tbody>${o.items.map(i=>`<tr><td>${esc(i.name)}</td><td>${esc(i.sku)}</td><td>${i.quantity}</td><td>${money(i.unitPrice)}</td><td>${money(i.unitPrice*i.quantity)}</td></tr>`).join('')}</tbody></table></div><div style="max-width:320px;margin:16px 0 0 auto">${[['Subtotal',o.subtotal],['Discount',-o.discount],['Shipping',o.shipping],['Tax',o.tax],['Total',o.total]].map(([l,v])=>`<div class="sum-line"><span>${l}</span><b>${money(v)}</b></div>`).join('')}</div></div></main>`}
function wishlistPage(){const products=state.wishlist.map(productById).filter(Boolean);return `<main class="page"><div class="page-title"><div><h1>Your wishlist</h1><p>Products saved for later.</p></div></div>${products.length?productGrid(products):`<div class="empty-state"><h3>Your wishlist is empty</h3><p>Save a product to find it quickly next time.</p><a href="/" data-route="/" class="btn secondary">Browse products</a></div>`}</main>`}
function staticPage(){const title=decodeURIComponent(location.pathname.split('/').pop());return `<main class="page"><div class="crumbs"><a href="/" data-route="/">Home</a> / ${esc(title)}</div><article class="surface" style="max-width:800px"><h1 class="page-title">${esc(title)}</h1><p>For help with ${esc(title.toLowerCase())}, contact our team at <a class="link-button" href="mailto:hello@techrefreshsolution.com">hello@techrefreshsolution.com</a>. Our support team will be happy to help with product selection, order status, shipping and warranty questions.</p></article></main>`}
function storefrontShell(content){return `${siteHeader()}${content}${footer()}<div class="toast-stack"></div>`}
function loadRazorpay(){if(window.Razorpay)return Promise.resolve();return new Promise((resolve,reject)=>{const script=document.createElement('script');script.src='https://checkout.razorpay.com/v1/checkout.js';script.onload=resolve;script.onerror=()=>reject(new Error('Could not load secure payment checkout. Check your internet connection and retry.'));document.head.append(script)})}
async function showOrderConfirmation(order,message){state.cart=[];setCart();state.couponCode='';state.userOrders=null;await refreshStore();app.innerHTML=storefrontShell(`<main class="page"><div class="empty-state"><span class="benefit-mark" style="margin:auto;width:44px;height:44px">✓</span><h3>Order confirmed</h3><p>Your order <b>${esc(order.id)}</b> is confirmed for ${money(order.total)}.</p><p>${esc(message)}</p><a class="btn primary" href="/invoice/${esc(order.id)}" data-route="/invoice/${esc(order.id)}">View order invoice</a> <a class="btn secondary" href="/orders" data-route="/orders">Track order</a></div></main>`);window.scrollTo(0,0)}

const adminTitles={dashboard:'Overview',products:'Products',categories:'Categories & attributes',orders:'Orders',customers:'Customers',marketing:'Promotions & content',reports:'Reports',settings:'Store settings',staff:'Team access'};
const adminIcons={dashboard:'⌂',products:'▦',categories:'◈',orders:'▤',customers:'♙',marketing:'✳',reports:'▥',settings:'⚙',staff:'♧'};
function adminRoute(){const path=location.pathname.split('/').filter(Boolean);const page=path[1]||'dashboard';if(page==='login')return {page:'login'};if(['new','edit'].includes(path[2]))return {page:page,mode:path[2],id:path[3]};return {page:adminTitles[page]?page:'dashboard'};}
function adminShell(page,content){const active=page;const nav=['dashboard','products','categories','orders','customers','marketing','reports'];const role=state.user?.role;const visible=nav.filter(p=>role==='super_admin'||role==='admin'||(role==='catalog_manager'&&['products','categories'].includes(p))||(role==='order_manager'&&['orders','customers'].includes(p)));if(role==='super_admin'||role==='admin')visible.push('staff','settings');return `<div class="admin-layout"><aside class="admin-sidebar"><a href="/admin" data-route="/admin" class="admin-brand">${image('/logo.png','Tech Refresh Solution')}<div><strong>TECH REFRESH</strong><small>STORE MANAGEMENT</small></div></a><div class="admin-label">Workspace</div><nav class="admin-nav">${visible.map(p=>`<a href="/admin${p==='dashboard'?'':`/${p}`}" data-route="/admin${p==='dashboard'?'':`/${p}`}" class="${active===p?'active':''}"><span class="nav-symbol">${adminIcons[p]}</span><span class="nav-text">${adminTitles[p]||p}</span></a>`).join('')}</nav><div class="admin-sidebar-bottom"><a href="/" data-route="/" title="View storefront"><span class="nav-symbol">↗</span><span class="nav-text">View storefront</span></a><button data-action="logout" title="Sign out"><span class="nav-symbol">⇥</span><span class="nav-text">Sign out</span></button></div></aside><div class="admin-main"><header class="admin-topbar"><h1>${adminTitles[page]||'Edit product'}</h1><div class="admin-user"><span>${esc(state.user?.name||'Administrator')}</span><span class="admin-avatar">${esc((state.user?.name||'A').slice(0,1).toUpperCase())}</span></div></header><main class="admin-content">${content}</main></div></div><div class="toast-stack"></div>`}
function statusPill(status){return `<span class="status-pill ${esc(String(status).toLowerCase().replaceAll(' ','-'))}">${esc(status)}</span>`}
function adminHead(title,desc,action=''){return `<div class="admin-page-head"><div><h2>${title}</h2><p>${desc}</p></div>${action}</div>`}
function adminStats(){const a=state.admin;const month=new Date();month.setDate(1);const orders=a.orders.filter(o=>new Date(o.createdAt)>=month);const sales=orders.filter(o=>o.status!=='cancelled').reduce((n,o)=>n+o.total,0);return `<section class="admin-stats"><div class="admin-stat"><div class="admin-stat-head"><span>Sales this month</span><i class="admin-stat-mark">₹</i></div><strong>${money(sales)}</strong><small>${orders.length} orders this month</small></div><div class="admin-stat"><div class="admin-stat-head"><span>Total orders</span><i class="admin-stat-mark">▤</i></div><strong>${a.orders.length}</strong><small>${a.orders.filter(o=>['processing','shipped'].includes(o.status)).length} in progress</small></div><div class="admin-stat"><div class="admin-stat-head"><span>Customers</span><i class="admin-stat-mark">♙</i></div><strong>${a.customers.length}</strong><small>Registered accounts</small></div><div class="admin-stat"><div class="admin-stat-head"><span>Low stock</span><i class="admin-stat-mark">!</i></div><strong>${a.products.filter(p=>p.stock<=Number(a.settings.lowStockThreshold)&&p.status==='published').length}</strong><small>At or below ${a.settings.lowStockThreshold} units</small></div></section>`}
function orderTable(orders,admin=false){if(!orders.length)return `<div class="empty-state"><h3>No orders to show</h3><p>Orders will appear when customers check out.</p></div>`;return `<div class="table-wrap"><table class="data-table"><thead><tr><th>Order</th><th>Customer</th><th>Date</th><th>Items</th><th>Total</th><th>Status</th>${admin?'<th>Update status</th>':''}</tr></thead><tbody>${orders.map(o=>`<tr><td><span class="table-main">${esc(o.id)}</span><div class="table-sub">${esc(o.paymentMethod==='cod'?'COD':'Online')}</div></td><td><span class="table-main">${esc(o.customerName)}</span><div class="table-sub">${esc(o.email)}</div></td><td>${date(o.createdAt)}</td><td>${o.items.reduce((n,i)=>n+i.quantity,0)}</td><td>${money(o.total)}</td><td>${statusPill(o.status)}</td>${admin?`<td><select class="admin-select" data-order-status="${esc(o.id)}"><option ${o.status==='processing'?'selected':''} value="processing">Processing</option><option ${o.status==='shipped'?'selected':''} value="shipped">Shipped</option><option ${o.status==='delivered'?'selected':''} value="delivered">Delivered</option><option ${o.status==='cancelled'?'selected':''} value="cancelled">Cancelled</option><option ${o.status==='returned'?'selected':''} value="returned">Returned</option></select></td>`:''}</tr>`).join('')}</tbody></table></div>`}
function dashboardPage(){const a=state.admin;const low=a.products.filter(p=>p.stock<=Number(a.settings.lowStockThreshold)&&p.status==='published');return `${adminStats()}<section class="admin-grid"><div class="admin-panel"><div class="admin-panel-head"><h3>Recent orders</h3><a href="/admin/orders" data-route="/admin/orders">View all →</a></div>${orderTable(a.orders.slice(0,5),false)}</div><div class="admin-panel"><div class="admin-panel-head"><h3>Stock to watch</h3><a href="/admin/products" data-route="/admin/products">Manage products →</a></div>${low.length?low.slice(0,6).map(p=>`<div class="orow"><span><b>${esc(p.name)}</b><br><small>${esc(p.sku)}</small></span><span class="status-pill pending">${p.stock} left</span></div>`).join(''):`<div class="empty-state"><p>All published products are above the low-stock threshold.</p></div>`}</div><div class="admin-panel"><div class="admin-panel-head"><h3>Sales snapshot</h3><a href="/admin/reports" data-route="/admin/reports">Open reports →</a></div>${salesChart(a.orders)}</div><div class="admin-panel"><div class="admin-panel-head"><h3>Quick actions</h3></div><div style="display:flex;flex-direction:column;gap:7px"><a class="btn secondary" href="/admin/products/new" data-route="/admin/products/new">＋ Add a product</a><a class="btn secondary" href="/admin/categories" data-route="/admin/categories">◈ Create category</a><a class="btn secondary" href="/admin/marketing" data-route="/admin/marketing">✳ Create an offer</a></div></div></section>`}
function salesChart(orders){const buckets=Array(7).fill(0);for(const o of orders){const days=Math.floor((Date.now()-new Date(o.createdAt).getTime())/86400000);if(days>=0&&days<7&&o.status!=='cancelled')buckets[6-days]+=o.total}const max=Math.max(...buckets,1);return `<div class="chart-bars">${buckets.map((v,i)=>`<div class="bar-col"><i style="height:${Math.max(2,Math.round(v/max*100))}%" title="${money(v)}"></i><span>${new Intl.DateTimeFormat('en-IN',{weekday:'short'}).format(Date.now()-(6-i)*86400000)}</span></div>`).join('')}</div>`}
function productsPage(){const search=new URLSearchParams(location.search).get('q')||'';let products=state.admin.products;if(search)products=products.filter(p=>`${p.name} ${p.sku}`.toLowerCase().includes(search.toLowerCase()));return `${adminHead('Product catalog','Manage pricing, product details and inventory.',`<a class="btn primary" href="/admin/products/new" data-route="/admin/products/new">＋ Add product</a>`)}<div class="toolbar"><div class="toolbar-left"><form id="admin-search" data-target="/admin/products"><input class="searchbox" name="q" placeholder="Search name or SKU" value="${esc(search)}"></form><select class="admin-select" data-admin-filter="product-status"><option value="">All statuses</option>${['published','draft','out_of_stock','discontinued'].map(s=>`<option value="${s}">${s.replaceAll('_',' ')}</option>`).join('')}</select><select class="admin-select" data-admin-filter="product-category"><option value="">All categories</option>${state.admin.categories.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select></div><div class="toolbar-right"><span class="form-help">${products.length} products · ${state.admin.categories.length} categories</span></div></div><div class="admin-panel">${products.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Product</th><th>Category</th><th>Price</th><th>Stock</th><th>Status</th><th>Updated</th><th>Actions</th></tr></thead><tbody>${products.map(p=>`<tr data-product-row data-status="${esc(p.status)}" data-category="${esc(p.categoryId)}"><td><div class="product-mini">${image(p.image,p.name)}<span><span class="table-main">${esc(p.name)}</span><div class="table-sub">${esc(p.sku)}</div></span></div></td><td>${esc(state.admin.categories.find(c=>c.id===p.categoryId)?.name||'-')}</td><td>${money(p.price)}${p.mrp>p.price?`<div class="table-sub">MRP ${money(p.mrp)}</div>`:''}</td><td>${p.stock}</td><td>${statusPill(p.status)}</td><td>${date(p.createdAt)}</td><td><div class="table-actions"><a href="/admin/products/edit/${p.id}" data-route="/admin/products/edit/${p.id}">Edit</a><button data-action="clone-product" data-id="${p.id}">Clone</button><button data-action="delete-product" data-id="${p.id}">Delete</button></div></td></tr>`).join('')}</tbody></table></div>`:`<div class="empty-state"><h3>No products match</h3><p>Add a product or adjust your search.</p></div>`}</div>`}
function categoriesPage(){const cats=state.admin.categories;return `${adminHead('Categories & attributes','Create category-specific fields. Product forms follow the selected category.',`<button class="btn primary" data-action="new-category">＋ Add category</button>`)}<div class="admin-panel"><div class="table-wrap"><table class="data-table"><thead><tr><th>Category</th><th>URL slug</th><th>Products</th><th>Custom attributes</th><th>Status</th><th>Actions</th></tr></thead><tbody>${cats.map(c=>`<tr><td><span class="table-main">${esc(c.name)}</span><div class="table-sub">${esc(c.description)}</div></td><td>${esc(c.slug)}</td><td>${state.admin.products.filter(p=>p.categoryId===c.id).length}</td><td>${c.attributes?.length||0}</td><td>${statusPill(c.active===false?'inactive':'active')}</td><td><div class="table-actions"><button data-action="edit-category" data-id="${c.id}">Edit fields</button><button data-action="deactivate-category" data-id="${c.id}">Deactivate</button></div></td></tr>`).join('')}</tbody></table></div><p class="form-help">Attribute types: text, number, dropdown, multi-select, checkbox, date and image. Required fields are checked before a product can be published.</p></div>`}
function productEditorBasicPage(route){const product=route.mode==='edit'?state.admin.products.find(p=>p.id===route.id):null;const categories=state.admin.categories.filter(c=>c.active!==false);const cat=categories.find(c=>c.id===(product?.categoryId||categories[0]?.id));if(!product&&route.mode==='edit')return `<div class="empty-state"><h3>Product not found</h3><a class="btn secondary" href="/admin/products" data-route="/admin/products">Back to products</a></div>`;return `${adminHead(product?'Edit product':'Add product',product?'Update product details, attributes and stock.':'Choose a category to load its custom fields.',`<a class="btn secondary" href="/admin/products" data-route="/admin/products">← Product catalog</a>`)}<form id="product-form" data-id="${product?.id||''}"><div class="editor-layout"><div><section class="editor-panel"><h3>Product information</h3><label class="form-field"><span>Product name</span><input name="name" required value="${esc(product?.name||'')}" placeholder="e.g. Business laptop"></label><div class="form-grid"><label class="form-field"><span>Category</span><select name="categoryId" id="product-category" required>${categories.map(c=>`<option value="${c.id}" ${c.id===product?.categoryId||(!product&&c.id===cat?.id)?'selected':''}>${esc(c.name)}</option>`).join('')}</select></label><label class="form-field"><span>SKU</span><input name="sku" required value="${esc(product?.sku||'')}" placeholder="TRS-XX-001"></label></div><label class="form-field"><span>Description</span><textarea name="description" placeholder="Product details, features and intended use">${esc(product?.description||'')}</textarea></label></section><section class="editor-panel"><h3 id="attribute-heading">${esc(cat?.name||'Category')} attributes</h3><div id="dynamic-attributes">${attributeInputs(cat,product)}</div><div class="form-help">These fields are configured under Categories & attributes.</div></section><section class="editor-panel"><h3>Search engine listing</h3><label class="form-field"><span>Page title</span><input name="seoTitle" value="${esc(product?.seo?.title||product?.name||'')}"></label><label class="form-field"><span>Meta description</span><textarea name="seoDescription">${esc(product?.seo?.description||'')}</textarea></label><label class="form-field"><span>URL slug</span><input name="slug" value="${esc(product?.slug||'')}" placeholder="generated-from-product-name"></label></section></div><div><section class="editor-panel"><h3>Media</h3><div class="image-preview" id="product-preview">${product?.image?image(product.image,product.name):'Product image preview'}</div><label class="form-field"><span>Image URL</span><input name="image" id="product-image" value="${esc(product?.image||'')}" placeholder="https://... or upload below"></label><label class="form-field"><span>Upload image</span><input type="file" id="product-upload" accept="image/png,image/jpeg,image/webp"></label><p class="form-help">PNG, JPEG or WebP · maximum 5 MB</p></section><section class="editor-panel"><h3>Price & inventory</h3><div class="form-grid"><label class="form-field"><span>Selling price (₹)</span><input type="number" min="0" name="price" required value="${esc(product?.price??'')}"></label><label class="form-field"><span>MRP (₹)</span><input type="number" min="0" name="mrp" value="${esc(product?.mrp??'')}"></label><label class="form-field"><span>Stock quantity</span><input type="number" min="0" name="stock" value="${esc(product?.stock??0)}"></label><label class="form-field"><span>Product status</span><select name="status">${['draft','published','out_of_stock','discontinued'].map(s=>`<option value="${s}" ${product?.status===s?'selected':''}>${s.replaceAll('_',' ').replace(/^./,c=>c.toUpperCase())}</option>`).join('')}</select></label></div><label class="check-line"><input type="checkbox" name="madeToOrder" ${product?.madeToOrder?'checked':''}> Made to order (no stock required)</label></section><section class="editor-panel"><h3>Publish</h3><p class="form-help">Published products need a category, price, image and available stock or made-to-order setting.</p><div id="product-error"></div><button class="btn primary full">${product?'Save changes':'Save product'}</button></section></div></div></form>`}
function variantEditorRow(variant={}){return `<div class="variant-row"><input type="hidden" name="variant-id" value="${esc(variant.id||'')}"><input name="variant-label" required placeholder="Option, e.g. Black · 16 GB" value="${esc(variant.label||'')}"><input name="variant-sku" required placeholder="SKU" value="${esc(variant.sku||'')}"><input name="variant-price" type="number" min="0" required placeholder="Price" value="${esc(variant.price??'')}"><input name="variant-stock" type="number" min="0" required placeholder="Stock" value="${esc(variant.stock??0)}"><button type="button" data-action="remove-variant" aria-label="Remove option">×</button></div>`}
function productEditorPage(route){const product=route.mode==='edit'?state.admin.products.find(p=>p.id===route.id):null;let html=productEditorBasicPage(route);if(!html.includes('id="product-form"'))return html;state.pendingProductImages=[...(product?.images?.length?product.images:product?.image?[product.image]:[])];const rows=(product?.variants||[]).map(variantEditorRow).join('');const panel=`<section class="editor-panel"><div class="admin-panel-head"><h3>Variants</h3><button type="button" class="btn small secondary" data-action="add-variant">＋ Add option</button></div><div class="form-help">Optional. Add combinations such as size and colour. Each option tracks its own price and stock. Leave empty for a simple product.</div><div id="variant-list" class="variant-list">${rows}</div></section>`;html=html.replace('id="product-upload" accept="image/png,image/jpeg,image/webp"','id="product-upload" accept="image/png,image/jpeg,image/webp" multiple').replace('<label class="form-field"><span>Upload image</span><input type="file" id="product-upload" accept="image/png,image/jpeg,image/webp" multiple></label>',`<label class="form-field"><span>Upload images</span><input type="file" id="product-upload" accept="image/png,image/jpeg,image/webp" multiple></label><div id="product-image-list" class="image-list">${renderImageList()}</div>`);return html.replace('<section class="editor-panel"><h3>Publish',`${panel}<section class="editor-panel"><h3>Publish`)}
function renderImageList(){return state.pendingProductImages.map((src,index)=>`<div class="image-item"><img src="${esc(src)}" alt="Product image ${index+1}"><span>${index===0?'Primary':`Image ${index+1}`}</span><button type="button" data-action="move-image" data-index="${index}" data-delta="-1" aria-label="Move image left" ${index===0?'disabled':''}>←</button><button type="button" data-action="move-image" data-index="${index}" data-delta="1" aria-label="Move image right" ${index===state.pendingProductImages.length-1?'disabled':''}>→</button><button type="button" data-action="remove-image" data-index="${index}" aria-label="Remove image">×</button></div>`).join('')}
function syncImageList(){const list=document.querySelector('#product-image-list');if(list)list.innerHTML=renderImageList();const first=state.pendingProductImages[0];const input=document.querySelector('#product-image');const preview=document.querySelector('#product-preview');if(input)input.value=first||'';if(preview)preview.innerHTML=first?image(first,'Product preview'):'Product image preview'}
function syncVariantBase(){const form=document.querySelector('#product-form');if(!form)return;const rows=[...form.querySelectorAll('.variant-row')];const price=form.elements.price,stock=form.elements.stock;price.required=!rows.length;price.disabled=Boolean(rows.length);stock.disabled=Boolean(rows.length);if(rows.length){const prices=rows.map(r=>Number(r.querySelector('[name=variant-price]').value)).filter(Number.isFinite);const quantities=rows.map(r=>Number(r.querySelector('[name=variant-stock]').value)||0);price.value=prices.length?Math.min(...prices):'';stock.value=quantities.reduce((n,v)=>n+v,0)}}
function attributeInputs(category,product=null){if(!category?.attributes?.length)return `<div class="empty-state"><p>This category has no custom attributes yet.</p><a class="link-button" href="/admin/categories" data-route="/admin/categories">Set up category attributes →</a></div>`;return category.attributes.map(a=>{const val=product?.attributes?.[a.name]??'';const req=a.required?'required':'';if(a.type==='checkbox')return `<label class="check-line"><input type="checkbox" name="attr:${esc(a.name)}" ${val?'checked':''}> ${esc(a.name)}${req?' *':''}</label>`;if(a.type==='dropdown'||a.type==='multiselect')return `<label class="form-field"><span>${esc(a.name)}${req?' *':''}</span><select name="attr:${esc(a.name)}" ${req}><option value="">Choose ${esc(a.name.toLowerCase())}</option>${(a.options||[]).map(v=>`<option value="${esc(v)}" ${val===v?'selected':''}>${esc(v)}</option>`).join('')}</select></label>`;if(a.type==='image')return `<label class="form-field"><span>${esc(a.name)}${req?' *':''}</span><input name="attr:${esc(a.name)}" value="${esc(val)}" placeholder="Image URL" ${req}></label>`;return `<label class="form-field"><span>${esc(a.name)}${req?' *':''}</span><input name="attr:${esc(a.name)}" type="${a.type==='number'?'number':a.type==='date'?'date':'text'}" value="${esc(val)}" ${req}></label>`}).join('')}
function ordersPage(){const orders=state.admin.orders;return `${adminHead('Orders','Review payment and fulfilment details. Updating to cancelled restores the reserved stock.') }<div class="toolbar"><div class="toolbar-left"><input class="searchbox" data-live-search="orders" placeholder="Search order or customer"></div><div class="toolbar-right"><span class="form-help">${orders.length} total orders</span></div></div><div class="admin-panel" id="order-table">${orderTable(orders,true)}</div>`}
function customersPage(){const customers=state.admin.customers;return `${adminHead('Customers','Registered customer profiles and order history.')}<div class="toolbar"><div class="toolbar-left"><input class="searchbox" data-live-search="customers" placeholder="Search name or email"></div><span class="form-help">${customers.length} customers</span></div><div class="admin-panel"><div class="table-wrap"><table class="data-table"><thead><tr><th>Customer</th><th>Phone</th><th>Joined</th><th>Orders</th><th>Lifetime value</th><th>Recent order</th></tr></thead><tbody>${customers.map(c=>{const orders=state.admin.orders.filter(o=>o.customerId===c.id);return `<tr data-customer-row><td><span class="table-main">${esc(c.name)}</span><div class="table-sub">${esc(c.email)}</div></td><td>${esc(c.phone||'-')}</td><td>${date(c.createdAt)}</td><td>${orders.length}</td><td>${money(orders.reduce((n,o)=>n+(o.status==='cancelled'?0:o.total),0))}</td><td>${orders[0]?esc(orders[0].id):'—'}</td></tr>`}).join('')||`<tr><td colspan="6">No registered customers yet.</td></tr>`}</tbody></table></div></div>`}
function marketingPage(){const coupons=state.admin.coupons;const banners=state.admin.banners;const pending=(state.admin.reviews||[]).filter(r=>r.status==='pending');return `${adminHead('Promotions & content','Manage discount codes, homepage banners and customer reviews.',`<button class="btn primary" data-action="new-coupon">＋ Create coupon</button>`)}<div class="admin-grid"><section class="admin-panel"><div class="admin-panel-head"><h3>Coupons</h3><button class="btn small secondary" data-action="new-coupon">＋ Coupon</button></div>${coupons.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Code</th><th>Offer</th><th>Minimum cart</th><th>Usage</th><th>Status</th></tr></thead><tbody>${coupons.map(c=>`<tr><td><span class="table-main">${esc(c.code)}</span></td><td>${c.type==='percent'?`${c.value}% off`:`${money(c.value)} off`}</td><td>${money(c.minimum||0)}</td><td>${c.used||0}${c.usageLimit?` / ${c.usageLimit}`:' / unlimited'}</td><td>${statusPill(c.active?'active':'inactive')}</td></tr>`).join('')}</tbody></table></div>`:`<div class="empty-state"><p>No coupons yet.</p></div>`}</section><section class="admin-panel"><div class="admin-panel-head"><h3>Homepage banners</h3><button class="btn small secondary" data-action="new-banner">＋ Banner</button></div>${banners.map(b=>`<div class="banner-row">${image(b.image,b.title)}<div><strong>${esc(b.title)}</strong><p>${esc(b.subtitle)}</p>${statusPill(b.active?'active':'inactive')}</div><button class="btn small secondary" data-action="toggle-banner" data-id="${b.id}">${b.active?'Pause':'Show'}</button></div>`).join('')||`<div class="empty-state"><p>No homepage banners.</p></div>`}</section><section class="admin-panel"><div class="admin-panel-head"><h3>Reviews awaiting approval</h3><span class="form-help">${pending.length} pending</span></div>${pending.map(r=>`<div class="order-card"><div class="order-top"><b>${esc(r.customerName)} · ${'★'.repeat(r.rating)}</b><span>${date(r.createdAt)}</span></div><div class="order-bottom"><span>${esc(state.admin.products.find(p=>p.id===r.productId)?.name||'Product')}<br>${esc(r.comment)}</span><span class="table-actions"><button data-action="moderate-review" data-id="${r.id}" data-status="approved">Approve</button><button data-action="moderate-review" data-id="${r.id}" data-status="rejected">Reject</button></span></div></div>`).join('')||`<p class="form-help">No reviews are waiting for approval.</p>`}</section></div>`}
function reportsPage(){const orders=state.admin.orders.filter(o=>o.status!=='cancelled');const byCategory={};for(const o of orders)for(const item of o.items){const p=state.admin.products.find(x=>x.id===item.productId);const name=state.admin.categories.find(c=>c.id===p?.categoryId)?.name||'Other';byCategory[name]=(byCategory[name]||0)+item.unitPrice*item.quantity}const max=Math.max(...Object.values(byCategory),1);const low=state.admin.products.filter(p=>p.stock<=Number(state.admin.settings.lowStockThreshold));const top=[...state.admin.products].sort((a,b)=>(b.sold||0)-(a.sold||0)).slice(0,5);return `${adminHead('Reports','Store performance, product movement and inventory health.') }<div class="report-filters"><label class="form-help">Date range</label><select class="admin-select" id="report-range"><option value="30">Last 30 days</option><option value="7">Last 7 days</option><option value="365">This year</option><option value="all">All time</option></select><button class="btn small secondary" data-action="export-orders">Export orders CSV</button></div><div class="admin-stats"><div class="admin-stat"><div class="admin-stat-head"><span>Net sales</span><i class="admin-stat-mark">₹</i></div><strong>${money(orders.reduce((n,o)=>n+o.total,0))}</strong><small>Across ${orders.length} orders</small></div><div class="admin-stat"><div class="admin-stat-head"><span>Average order</span><i class="admin-stat-mark">↗</i></div><strong>${money(orders.length?orders.reduce((n,o)=>n+o.total,0)/orders.length:0)}</strong><small>Net of cancelled orders</small></div><div class="admin-stat"><div class="admin-stat-head"><span>Low-stock items</span><i class="admin-stat-mark">!</i></div><strong>${low.length}</strong><small>Threshold: ${state.admin.settings.lowStockThreshold}</small></div><div class="admin-stat"><div class="admin-stat-head"><span>Abandoned carts</span><i class="admin-stat-mark">▱</i></div><strong>—</strong><small>Requires persistent cart analytics</small></div></div><div class="admin-grid"><section class="admin-panel"><div class="admin-panel-head"><h3>Revenue by category</h3></div>${Object.keys(byCategory).length?Object.entries(byCategory).map(([name,val])=>`<div class="metric-line"><span>${esc(name)}</span><i><b style="width:${Math.max(3,val/max*100)}%"></b></i><b>${money(val)}</b></div>`).join(''):`<div class="empty-state"><p>Category sales appear after the first order.</p></div>`}</section><section class="admin-panel"><div class="admin-panel-head"><h3>Top products</h3></div>${top.map(p=>`<div class="orow"><span><b>${esc(p.name)}</b><br><small>${esc(p.sku)}</small></span><span>${money(p.price)}</span></div>`).join('')}</section><section class="admin-panel"><div class="admin-panel-head"><h3>Inventory alerts</h3><a href="/admin/products" data-route="/admin/products">Product catalog →</a></div>${low.length?low.map(p=>`<div class="orow"><span><b>${esc(p.name)}</b><br><small>${esc(p.sku)}</small></span><span class="status-pill pending">${p.stock} left</span></div>`).join(''):`<p class="form-help">No products are below the configured stock threshold.</p>`}</section><section class="admin-panel"><div class="admin-panel-head"><h3>Audit activity</h3></div>${state.admin.audit.slice(0,6).map(x=>`<div class="orow"><span>${esc(x.action)}<br><small>${esc(x.actor)}</small></span><span>${date(x.at)}</span></div>`).join('')||`<p class="form-help">Store changes will appear here.</p>`}</section></div>`}
function settingsPage(){const s=state.admin.settings;return `${adminHead('Store settings','Configure checkout costs, brand details and customer support.') }<form id="settings-form" class="settings-form"><section class="editor-panel"><h3>Store identity</h3><label class="form-field"><span>Store name</span><input name="brandName" value="${esc(s.brandName)}"></label><label class="form-field"><span>Support email</span><input name="supportEmail" type="email" value="${esc(s.supportEmail)}"></label></section><section class="editor-panel"><h3>Checkout & inventory</h3><div class="settings-row"><div><strong>Tax rate</strong><small>Applied to the discounted subtotal.</small></div><input class="input" name="taxRate" type="number" min="0" max="100" step="0.1" value="${s.taxRate}"></div><div class="settings-row"><div><strong>Standard shipping</strong><small>Charged below the free-shipping threshold.</small></div><input class="input" name="shippingFlat" type="number" min="0" value="${s.shippingFlat}"></div><div class="settings-row"><div><strong>Free shipping at</strong><small>Order subtotal threshold in rupees.</small></div><input class="input" name="freeShippingAt" type="number" min="0" value="${s.freeShippingAt}"></div><div class="settings-row"><div><strong>Low-stock alert threshold</strong><small>Products at or below this quantity are flagged.</small></div><input class="input" name="lowStockThreshold" type="number" min="0" value="${s.lowStockThreshold}"></div><div class="settings-row"><div><strong>Cash on delivery</strong><small>Offer COD at checkout.</small></div><span class="toggle-control"><input class="switch" name="codEnabled" type="checkbox" ${s.codEnabled?'checked':''}></span></div><div class="settings-row"><div><strong>Razorpay</strong><small>Credentials are loaded securely from the backend environment.</small></div><span class="status-pill ${s.onlinePaymentEnabled?'active':'pending'}">${s.onlinePaymentEnabled?'Connected':'Keys missing'}</span></div></section><div id="settings-error"></div><button class="btn primary">Save settings</button></form>`}
function staffPage(){return `${adminHead('Team access','Create staff logins with catalog-only or order-only access.',`<button class="btn primary" data-action="new-staff">＋ Add staff member</button>`)}<div class="admin-panel"><div class="table-wrap"><table class="data-table"><thead><tr><th>Team member</th><th>Role</th><th>Access</th></tr></thead><tbody>${state.admin.admins.map(u=>`<tr><td><span class="table-main">${esc(u.name)}</span><div class="table-sub">${esc(u.email)}</div></td><td>${esc(u.role.replaceAll('_',' '))}</td><td>${u.role==='super_admin'?'All store settings and operations':u.role==='catalog_manager'?'Categories, products and inventory':'Orders and customer profiles'}</td></tr>`).join('')}</tbody></table></div><p class="form-help">Staff passwords are stored as one-way hashes. Give each person a unique login.</p></div>`}
function loginAdmin(){return `<main class="page"><section class="auth-layout"><div class="auth-intro"><img src="/logo.png" alt="Tech Refresh Solution"><div><h2>Store operations, in one place.</h2><p>Manage the catalog, customer orders and inventory.</p></div></div><div class="auth-main"><h1>Admin sign in</h1><p>Use your administrator or staff account.</p><form id="admin-login-form"><label class="form-field"><span>Email address</span><input name="email" type="email" required autocomplete="username"></label><label class="form-field"><span>Password</span><input name="password" type="password" required autocomplete="current-password"></label><div id="auth-error"></div><button class="btn primary full">Sign in to admin</button></form></div></section></main>`}
function categoryModal(category=null){return `<div class="modal-backdrop" data-modal-close><section class="modal" role="dialog" aria-modal="true" aria-labelledby="category-modal-title"><div class="modal-head"><h2 id="category-modal-title">${category?'Edit category':'Create category'}</h2><button class="modal-close" data-action="close-modal" aria-label="Close">×</button></div><form id="category-form" data-id="${category?.id||''}"><label class="form-field"><span>Name</span><input name="name" required value="${esc(category?.name||'')}"></label><label class="form-field" style="margin-top:9px"><span>Description</span><input name="description" value="${esc(category?.description||'')}"></label><div style="display:flex;justify-content:space-between;align-items:center;margin-top:15px"><b style="font-size:11px">Custom product attributes</b><button type="button" class="btn small secondary" data-action="add-attribute">＋ Attribute</button></div><div class="attribute-editor" id="attribute-list">${(category?.attributes||[]).map(attributeRow).join('')}</div><div class="modal-actions"><button type="button" class="btn secondary" data-action="close-modal">Cancel</button><button class="btn primary">Save category</button></div></form></section></div>`}
function attributeRow(attr={name:'',type:'text',options:[],required:false,filterable:false}){return `<div class="attribute-row"><input name="attr-name" placeholder="Attribute name" value="${esc(attr.name)}"><select name="attr-type">${['text','number','dropdown','multiselect','checkbox','date','image'].map(t=>`<option value="${t}" ${attr.type===t?'selected':''}>${t}</option>`).join('')}</select><label title="Required"><input name="attr-required" type="checkbox" ${attr.required?'checked':''}> Req</label><label title="Filterable"><input name="attr-filterable" type="checkbox" ${attr.filterable?'checked':''}> Filter</label><button type="button" data-action="remove-attribute" aria-label="Remove attribute">×</button><input class="attribute-options" name="attr-options" placeholder="Dropdown options, separated by commas" value="${esc((attr.options||[]).join(', '))}" style="grid-column:1/-1;${['dropdown','multiselect'].includes(attr.type)?'':'display:none'}"></div>`}
function genericModal(kind){const cfg={coupon:{title:'Create coupon',fields:`<label class="form-field"><span>Coupon code</span><input name="code" required placeholder="WELCOME15"></label><div class="form-grid"><label class="form-field"><span>Discount type</span><select name="type"><option value="percent">Percentage</option><option value="flat">Fixed amount</option></select></label><label class="form-field"><span>Discount value</span><input name="value" type="number" min="1" required></label><label class="form-field"><span>Minimum cart total</span><input name="minimum" type="number" min="0" value="0"></label><label class="form-field"><span>Usage limit (0 = unlimited)</span><input name="usageLimit" type="number" min="0" value="0"></label></div>`},banner:{title:'Add homepage banner',fields:`<label class="form-field"><span>Headline</span><input name="title" required></label><label class="form-field"><span>Supporting text</span><input name="subtitle"></label><label class="form-field"><span>Image URL</span><input name="image" placeholder="https://..."></label>`},staff:{title:'Add staff member',fields:`<label class="form-field"><span>Full name</span><input name="name" required></label><label class="form-field"><span>Email</span><input name="email" type="email" required></label><label class="form-field"><span>Temporary password</span><input name="password" type="password" minlength="8" required></label><label class="form-field"><span>Access role</span><select name="role"><option value="catalog_manager">Catalog manager</option><option value="order_manager">Order manager</option></select></label>`}}[kind];return `<div class="modal-backdrop" data-modal-close><section class="modal" role="dialog" aria-modal="true"><div class="modal-head"><h2>${cfg.title}</h2><button class="modal-close" data-action="close-modal" aria-label="Close">×</button></div><form id="${kind}-form">${cfg.fields}<div id="modal-error"></div><div class="modal-actions"><button type="button" class="btn secondary" data-action="close-modal">Cancel</button><button class="btn primary">Save</button></div></form></section></div>`}

async function render(){
  const route=location.pathname;
  if(route.startsWith('/admin')){
    const r=adminRoute();
    if(r.page==='login')return app.innerHTML=loginAdmin();
    if(!state.user||state.user.kind!=='admin')return app.innerHTML=loginAdmin();
    try{if(!state.admin)await refreshAdmin()}catch(error){if(error.status===401){state.user=null;return app.innerHTML=loginAdmin()}toast(error.message,true)}
    let content='';if(r.mode)content=productEditorPage(r);else if(r.page==='dashboard')content=dashboardPage();else if(r.page==='products')content=productsPage();else if(r.page==='categories')content=categoriesPage();else if(r.page==='orders')content=ordersPage();else if(r.page==='customers')content=customersPage();else if(r.page==='marketing')content=marketingPage();else if(r.page==='reports')content=reportsPage();else if(r.page==='settings')content=settingsPage();else if(r.page==='staff')content=staffPage();
    app.innerHTML=adminShell(r.mode?'products':r.page,content);if(r.mode)syncVariantBase();return;
  }
  if(route==='/account'&&state.user?.kind==='customer'&&!state.userOrders){try{state.userOrders=(await request('/api/account/orders')).orders}catch{state.userOrders=[]}}
  if(route.startsWith('/invoice/')&&!state.userOrders&&state.user?.kind==='customer'){try{state.userOrders=(await request('/api/account/orders')).orders}catch{}}
  if(route.startsWith('/product/')&&state.user?.kind==='customer'&&!state.userOrders){try{state.userOrders=(await request('/api/account/orders')).orders}catch{state.userOrders=[]}}
  let content;
  if(route==='/')content=homePage();else if(route.startsWith('/category/')||route==='/search')content=catalogPage();else if(route.startsWith('/product/'))content=productPage();else if(route==='/cart')content=cartPage();else if(route==='/checkout')content=checkoutPage();else if(route==='/account')content=accountPage();else if(route==='/login'||route==='/register')content=authPage(route==='/register'?'register':'login',new URLSearchParams(location.search).get('next')||'/account');else if(route==='/wishlist')content=wishlistPage();else if(route==='/orders'){if(!state.user)content=authPage('login','/orders');else if(state.user.kind==='admin')content=accountPage();else{try{if(!state.userOrders)state.userOrders=(await request('/api/account/orders')).orders}catch{state.userOrders=[]}content=`<main class="page"><div class="page-title"><div><h1>Your orders</h1><p>Order status and invoice details.</p></div></div>${state.userOrders.length?state.userOrders.map(orderCard).join(''):`<div class="empty-state"><h3>No orders yet</h3><p>Placed orders will appear here.</p></div>`}</main>`}}else if(route.startsWith('/invoice/'))content=invoicePage();else if(route.startsWith('/info/'))content=staticPage();else content=`<main class="page"><div class="empty-state"><h3>Page not found</h3><p>The page you requested isn’t available.</p><a href="/" data-route="/" class="btn secondary">Return to shop</a></div></main>`;
  app.innerHTML=storefrontShell(content);
}

async function init(){try{const session=await request('/api/session');state.user=session.user;state.csrf=session.csrf;await refreshStore();await render()}catch(error){app.innerHTML=`<main class="page"><div class="empty-state"><h3>Store unavailable</h3><p>${esc(error.message)}</p></div></main>`}}
function setCart(){saveLocal(cartKey,state.cart)}
function addToCart(id,qty=1,variantId=''){const p=productById(id);if(!p)return toast('This product is no longer available.',true);const variant=p.variants?.length?(p.variants.find(v=>v.id===variantId)||selectedVariant(p)):null;const available=variant?variant.stock:p.stock;if(!p.madeToOrder&&available<qty)return toast(`Only ${available} available.`,true);const line=state.cart.find(x=>x.productId===id&&(x.variantId||'')===(variant?.id||''));if(line){if(!p.madeToOrder&&line.quantity+qty>available)return toast(`Only ${available} available.`,true);line.quantity+=qty}else state.cart.push({productId:id,variantId:variant?.id||'',variantLabel:variant?.label||'',quantity:qty});setCart();toast(`${p.name}${variant?` · ${variant.label}`:''} added to your cart.`);render()}
function setQuantity(id,delta,variantId=''){const line=state.cart.find(x=>x.productId===id&&(x.variantId||'')===variantId);const p=productById(id);if(!line||!p)return;const variant=p.variants?.find(v=>v.id===variantId);const available=variant?variant.stock:p.stock;line.quantity+=delta;if(line.quantity<1)state.cart=state.cart.filter(x=>x!==line);else if(!p.madeToOrder&&line.quantity>available){line.quantity=available;toast(`Only ${available} available.`,true)}setCart();render()}
async function login(form,admin=false){const data=Object.fromEntries(new FormData(form));try{const result=await request('/api/account/login',{method:'POST',body:data});if(admin&&result.user.kind!=='admin')throw new Error('This sign-in is for store administrators and staff.');state.user=result.user;state.csrf=result.csrf;state.admin=null;state.userOrders=null;const next=form.dataset.next|| (admin||result.user.kind==='admin'?'/admin':'/account');history.replaceState({},'',next);await render();toast('You’re signed in.')}catch(error){const target=document.querySelector('#auth-error');if(target)target.innerHTML=`<div class="form-error">${esc(error.message)}</div>`}}
async function submitForm(event){const form=event.target;event.preventDefault();const fd=new FormData(form);const data=Object.fromEntries(fd.entries());
  if(form.id==='search-form'){const q=data.q.trim();routeTo(q?`/search?q=${encodeURIComponent(q)}`:'/');return}
  if(form.id==='admin-search'){const q=data.q.trim();routeTo(q?`/admin/products?q=${encodeURIComponent(q)}`:'/admin/products');return}
  if(form.id==='login-form'||form.id==='admin-login-form')return login(form,form.id==='admin-login-form');
  if(form.id==='register-form'){try{const result=await request('/api/account/register',{method:'POST',body:data});state.user=result.user;state.csrf=result.csrf;const next=form.dataset.next||'/account';history.replaceState({},'',next);await render();toast('Your account is ready.')}catch(error){document.querySelector('#auth-error').innerHTML=`<div class="form-error">${esc(error.message)}</div>`}return}
  if(form.id==='checkout-form'){
    const address={name:data.name,phone:data.phone,line1:data.line1,line2:data.line2,city:data.city,state:data.state,postalCode:data.postalCode};const button=form.querySelector('button[type=submit]');button.disabled=true;button.textContent='Placing order…';
    try{
      const result=await request('/api/checkout',{method:'POST',body:{items:state.cart,paymentMethod:data.paymentMethod,couponCode:state.couponCode,address}});
      if(data.paymentMethod==='gateway'){
        await loadRazorpay();
        const checkout=new window.Razorpay({key:result.payment.keyId,amount:result.payment.amount,currency:result.payment.currency,name:result.payment.brandName,order_id:result.payment.orderId,prefill:result.payment.prefill,theme:{color:'#246b55'},handler:async response=>{
          try{const verified=await request('/api/payment/verify',{method:'POST',body:response});await showOrderConfirmation(verified.order,'Payment verified and order confirmed.');}
          catch(error){const slot=document.querySelector('#checkout-error');if(slot)slot.innerHTML=`<div class="form-error">${esc(error.message)}</div>`;button.disabled=false;button.textContent=`Pay ${money(quote().total)}`}
        },modal:{ondismiss:()=>{button.disabled=false;button.textContent=`Pay ${money(quote().total)}`;const slot=document.querySelector('#checkout-error');if(slot)slot.innerHTML='<div class="form-help">Payment was not completed. Your cart is still saved.</div>'}}});
        checkout.open();return;
      }
      await showOrderConfirmation(result.order,result.payment.message);
    }catch(error){const slot=document.querySelector('#checkout-error');if(slot)slot.innerHTML=`<div class="form-error">${esc(error.message)}</div>`;button.disabled=false;button.textContent=`Place order · ${money(quote().total)}`}
    return;
  }
  if(form.id==='review-form'){try{await request('/api/reviews',{method:'POST',body:data});await refreshStore();await render();toast('Thanks for sharing your review.')}catch(error){toast(error.message,true)}return}
  if(form.id==='profile-form'){try{const result=await request('/api/account/profile',{method:'PATCH',body:{name:data.name,phone:data.phone}});state.user=result.user;await render();toast('Profile saved.')}catch(error){document.querySelector('#profile-result').innerHTML=`<div class="form-error">${esc(error.message)}</div>`}return}
  if(form.id==='address-form'){const address={name:data.name,phone:data.phone,line1:data.line1,line2:data.line2,city:data.city,state:data.state,postalCode:data.postalCode};try{const result=await request('/api/account/profile',{method:'PATCH',body:{addresses:[...(state.user.addresses||[]),address]}});state.user=result.user;state.accountTab='addresses';await render();toast('Address saved.')}catch(error){document.querySelector('#address-result').innerHTML=`<div class="form-error">${esc(error.message)}</div>`}return}
  if(form.id==='product-form'){
    const category=state.admin.categories.find(c=>c.id===data.categoryId);const attributes={};for(const a of category?.attributes||[]){const field=form.elements[`attr:${a.name}`];if(field)attributes[a.name]=a.type==='checkbox'?field.checked:field.value.trim()}
    const variants=[...form.querySelectorAll('.variant-row')].map(row=>({id:row.querySelector('[name=variant-id]').value,label:row.querySelector('[name=variant-label]').value.trim(),sku:row.querySelector('[name=variant-sku]').value.trim(),price:Number(row.querySelector('[name=variant-price]').value),stock:Number(row.querySelector('[name=variant-stock]').value)}));
    const button=form.querySelector('button[type=submit]')||form.querySelector('button');button.disabled=true;
    try{const images=state.pendingProductImages.length?[...state.pendingProductImages]:data.image?[data.image]:[];const basePrice=variants.length?Math.min(...variants.map(v=>v.price)):Number(data.price);const payload={name:data.name.trim(),categoryId:data.categoryId,sku:data.sku.trim(),description:data.description,price:basePrice,mrp:Number(data.mrp||basePrice),stock:variants.length?variants.reduce((n,v)=>n+v.stock,0):Number(data.stock||0),variants,status:data.status,madeToOrder:form.elements.madeToOrder.checked,image:images[0]||'',images,attributes,slug:data.slug,seo:{title:data.seoTitle,description:data.seoDescription}};const id=form.dataset.id;if(id)await request(`/api/admin/products/${id}`,{method:'PATCH',body:payload});else await request('/api/admin/products',{method:'POST',body:payload});await refreshAdmin();toast(id?'Product updated.':'Product created.');routeTo('/admin/products')}catch(error){const slot=document.querySelector('#product-error');if(slot)slot.innerHTML=`<div class="form-error">${esc(error.message)}</div>`;button.disabled=false}return;
  }
  if(form.id==='settings-form'){const payload={...data,codEnabled:form.elements.codEnabled.checked};for(const k of ['taxRate','shippingFlat','freeShippingAt','lowStockThreshold'])payload[k]=Number(payload[k]);try{await request('/api/admin/settings',{method:'PATCH',body:payload});await refreshAdmin();toast('Store settings saved.');await render()}catch(error){document.querySelector('#settings-error').innerHTML=`<div class="form-error">${esc(error.message)}</div>`}return}
  const mapping={'category-form':'categories','coupon-form':'coupons','banner-form':'banners','staff-form':'staff'};const kind=mapping[form.id];if(kind){let payload=data;if(kind==='categories'){payload={...data,attributes:[...form.querySelectorAll('.attribute-row')].map(row=>({name:row.querySelector('[name=attr-name]').value.trim(),type:row.querySelector('[name=attr-type]').value,options:row.querySelector('[name=attr-options]').value.split(',').map(s=>s.trim()).filter(Boolean),required:row.querySelector('[name=attr-required]').checked,filterable:row.querySelector('[name=attr-filterable]').checked})).filter(a=>a.name)}}if(kind==='coupons')payload={...data,value:Number(data.value),minimum:Number(data.minimum),usageLimit:Number(data.usageLimit)};try{if(form.dataset.id)await request(`/api/admin/categories/${form.dataset.id}`,{method:'PATCH',body:payload});else await request(`/api/admin/${kind}`,{method:'POST',body:payload});await refreshAdmin();document.querySelector('.modal-backdrop')?.remove();await render();toast('Saved successfully.')}catch(error){const slot=document.querySelector('#modal-error');if(slot)slot.innerHTML=`<div class="form-error">${esc(error.message)}</div>`}return}
}

document.addEventListener('click',async event=>{
  const link=event.target.closest('[data-route]');if(link){event.preventDefault();const next=link.dataset.route;const suffix=link.dataset.next?`?next=${encodeURIComponent(link.dataset.next)}`:'';routeTo(next+suffix);return}
  const accountTab=event.target.closest('[data-account-tab]');if(accountTab){state.accountTab=accountTab.dataset.accountTab;return render()}
  const staticLink=event.target.closest('[data-static]');if(staticLink){event.preventDefault();return routeTo(`/info/${encodeURIComponent(staticLink.dataset.static)}`)}
  const button=event.target.closest('[data-action]');if(!button)return;const {action,id}=button.dataset;
  if(action==='add-cart')return addToCart(id,button.dataset.detail?Number(document.querySelector('#detail-qty')?.textContent||1):1,button.dataset.variantId||'');
  if(action==='buy-now'){addToCart(id,1,button.dataset.variantId||'');return routeTo('/checkout')}
  if(action==='wish'){state.wishlist=state.wishlist.includes(id)?state.wishlist.filter(x=>x!==id):[...state.wishlist,id];saveLocal(wishKey,state.wishlist);toast(state.wishlist.includes(id)?'Saved to wishlist.':'Removed from wishlist.');return render()}
  if(action==='qty')return setQuantity(id,Number(button.dataset.delta),button.dataset.variantId||'');
  if(action==='detail-qty'){const el=document.querySelector('#detail-qty');el.textContent=String(Math.max(1,Number(el.textContent)+Number(button.dataset.delta)));return}
  if(action==='remove-cart'){state.cart=state.cart.filter(x=>!(x.productId===id&&(x.variantId||'')===(button.dataset.variantId||'')));setCart();return render()}
  if(action==='clear-cart'){state.cart=[];setCart();return render()}
  if(action==='clear-filters'){state.listing.filters={};return render()}
  if(action==='checkout'){if(!state.user) return routeTo('/login?next=%2Fcheckout');return routeTo('/checkout')}
  if(action==='apply-coupon'){const input=document.querySelector('#coupon-code');const code=input.value.trim().toUpperCase();const found=state.store.coupons.find(c=>c.code===code);if(found&&quote().subtotal>=Number(found.minimum||0)){state.couponCode=code;state.couponMessage=`${code} applied. Your discount will be confirmed at checkout.`}else{state.couponCode='';state.couponMessage=found?`Add ${money(found.minimum)} to use ${code}.`:'That code is not active.'}return render()}
  if(action==='logout'){try{await request('/api/account/logout',{method:'POST',body:{}})}catch{}state.user=null;state.userOrders=null;state.admin=null;state.csrf='';await init();toast('You’re signed out.');return}
  if(action==='new-category'){document.body.insertAdjacentHTML('beforeend',categoryModal());return}
  if(action==='edit-category'){document.body.insertAdjacentHTML('beforeend',categoryModal(state.admin.categories.find(c=>c.id===id)));return}
  if(action==='close-modal'){button.closest('.modal-backdrop')?.remove();return}
  if(action==='add-attribute'){document.querySelector('#attribute-list').insertAdjacentHTML('beforeend',attributeRow());return}
  if(action==='remove-attribute'){button.closest('.attribute-row').remove();return}
  if(action==='add-variant'){document.querySelector('#variant-list').insertAdjacentHTML('beforeend',variantEditorRow());syncVariantBase();return}
  if(action==='remove-variant'){button.closest('.variant-row').remove();syncVariantBase();return}
  if(action==='remove-image'){state.pendingProductImages.splice(Number(button.dataset.index),1);syncImageList();return}
  if(action==='move-image'){const i=Number(button.dataset.index),j=i+Number(button.dataset.delta);if(j>=0&&j<state.pendingProductImages.length){[state.pendingProductImages[i],state.pendingProductImages[j]]=[state.pendingProductImages[j],state.pendingProductImages[i]];syncImageList()}return}
  if(action==='select-product-image'){state.selectedImages[id]=button.dataset.src;return render()}
  if(action==='new-coupon'){document.body.insertAdjacentHTML('beforeend',genericModal('coupon'));return}
  if(action==='new-banner'){document.body.insertAdjacentHTML('beforeend',genericModal('banner'));return}
  if(action==='new-staff'){document.body.insertAdjacentHTML('beforeend',genericModal('staff'));return}
  if(action==='toggle-banner'){const b=state.admin.banners.find(x=>x.id===id);try{await request(`/api/admin/banners/${id}`,{method:'PATCH',body:{active:!b.active}});await refreshAdmin();await render()}catch(e){toast(e.message,true)}return}
  if(action==='deactivate-category'){if(!confirm('Deactivate this category? Existing products must be moved or removed first.'))return;try{await request(`/api/admin/categories/${id}`,{method:'DELETE'});await refreshAdmin();await render();toast('Category deactivated.')}catch(e){toast(e.message,true)}return}
  if(action==='delete-product'){if(!confirm('Delete this product from the catalog?'))return;try{await request(`/api/admin/products/${id}`,{method:'DELETE'});await refreshAdmin();await render();toast('Product deleted.')}catch(e){toast(e.message,true)}return}
  if(action==='clone-product'){const p=state.admin.products.find(x=>x.id===id);if(!p)return;const copy={...p,name:`${p.name} copy`,sku:`${p.sku}-COPY`,slug:'',status:'draft'};try{await request('/api/admin/products',{method:'POST',body:copy});await refreshAdmin();await render();toast('Draft copy created.')}catch(e){toast(e.message,true)}return}
  if(action==='export-orders'){return exportCsv(state.admin.orders)}
  if(action==='moderate-review'){try{await request(`/api/admin/reviews/${id}`,{method:'PATCH',body:{status:button.dataset.status}});await refreshAdmin();await render();toast(`Review ${button.dataset.status}.`)}catch(e){toast(e.message,true)}return}
  if(action==='delete-address'){const addresses=(state.user.addresses||[]).filter((_,i)=>i!==Number(button.dataset.index));try{const result=await request('/api/account/profile',{method:'PATCH',body:{addresses}});state.user=result.user;state.accountTab='addresses';await render();toast('Address removed.')}catch(e){toast(e.message,true)}return}
});
document.addEventListener('submit',submitForm);
document.addEventListener('change',async event=>{
  const el=event.target;
  if(el.matches('[name=variant-price],[name=variant-stock]')){syncVariantBase();return}
  if(el.id==='product-category'){const cat=state.admin.categories.find(c=>c.id===el.value);document.querySelector('#attribute-heading').textContent=`${cat?.name||'Category'} attributes`;document.querySelector('#dynamic-attributes').innerHTML=attributeInputs(cat);return}
  if(el.id==='checkout-address'){const address=state.user.addresses?.[Number(el.value)];if(address)for(const key of ['name','phone','line1','line2','city','state','postalCode']){const field=document.querySelector(`#checkout-form [name="${key}"]`);if(field)field.value=address[key]||''}return}
  if(el.id==='variant-choice'){const product=state.store.products.find(p=>p.slug===decodeURIComponent(location.pathname.split('/').pop()));if(product){state.selectedVariants[product.id]=el.value;return render()}}
  if(el.matches('[data-filter]')){state.listing.filters[el.dataset.filter]=el.checked;return render()}
  if(el.matches('[data-filter-value]')){state.listing.filters[el.dataset.filterValue]=el.value;return render()}
  if(el.matches('[data-filter-attr]')){state.listing.filters.attrs={...state.listing.filters.attrs,[el.dataset.filterAttr]:el.value};return render()}
  if(el.matches('[data-action="sort"]')){const params=new URLSearchParams(location.search);params.set('sort',el.value);history.replaceState({},'',`${location.pathname}?${params.toString()}`);return render()}
  if(el.matches('[data-order-status]')){try{await request(`/api/admin/orders/${el.dataset.orderStatus}`,{method:'PATCH',body:{status:el.value}});await refreshAdmin();toast('Order status updated.');return render()}catch(e){toast(e.message,true);return render()}}
  if(el.id==='product-image'){document.querySelector('#product-preview').innerHTML=el.value?image(el.value,'Product preview'):'Product image preview'}
  if(el.id==='product-upload'&&el.files?.length){for(const file of [...el.files]){if(file.size>5*1024*1024){toast(`${file.name} is larger than 5 MB.`,true);continue}try{const dataUrl=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(file)});const {url}=await request('/api/admin/upload',{method:'POST',body:{data:dataUrl}});state.pendingProductImages.push(url)}catch(e){toast(e.message,true)}}if(state.pendingProductImages.length)document.querySelector('#product-image').value=state.pendingProductImages[0];syncImageList();el.value=''}
  if(el.matches('[data-admin-filter]')){const rows=[...document.querySelectorAll('[data-product-row]')];for(const row of rows){const status=document.querySelector('[data-admin-filter="product-status"]').value;const cat=document.querySelector('[data-admin-filter="product-category"]').value;row.hidden=Boolean((status&&row.dataset.status!==status)||(cat&&row.dataset.category!==cat))}}
  if(el.id==='report-range'){const days=el.value==='all'?Infinity:Number(el.value);document.querySelectorAll('[data-report-item]').forEach(item=>{const age=(Date.now()-Number(item.dataset.reportItem))/86400000;item.hidden=age>days})}
});
document.addEventListener('input',event=>{const el=event.target;if(el.id==='product-image'){const value=el.value.trim();if(value){if(state.pendingProductImages.length)state.pendingProductImages[0]=value;else state.pendingProductImages.push(value)}else state.pendingProductImages.shift();const preview=document.querySelector('#product-preview');if(preview)preview.innerHTML=value?image(value,'Product preview'):'Product image preview';const list=document.querySelector('#product-image-list');if(list)list.innerHTML=renderImageList()}if(el.matches('[data-live-search="orders"]')){const value=el.value.toLowerCase();document.querySelectorAll('#order-table tbody tr').forEach(row=>row.hidden=!row.innerText.toLowerCase().includes(value))}if(el.matches('[data-live-search="customers"]')){const value=el.value.toLowerCase();document.querySelectorAll('[data-customer-row]').forEach(row=>row.hidden=!row.innerText.toLowerCase().includes(value))}if(el.matches('[name=attr-type]')){const options=el.closest('.attribute-row').querySelector('[name=attr-options]');options.style.display=['dropdown','multiselect'].includes(el.value)?'block':'none'}});
document.addEventListener('keydown',event=>{if(event.key==='Escape')document.querySelector('.modal-backdrop')?.remove()});
window.addEventListener('popstate',()=>render());
function exportCsv(orders){const quoteCsv=v=>`"${String(v??'').replaceAll('"','""')}"`;const rows=[['Order','Customer','Email','Date','Status','Payment','Subtotal','Discount','Shipping','Tax','Total'],...orders.map(o=>[o.id,o.customerName,o.email,o.createdAt,o.status,o.paymentMethod,o.subtotal,o.discount,o.shipping,o.tax,o.total])];const blob=new Blob([rows.map(r=>r.map(quoteCsv).join(',')).join('\r\n')],{type:'text/csv'});const link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download='tech-refresh-orders.csv';link.click();URL.revokeObjectURL(link.href)}
init();
